import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _norm_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        s = value.strip()
        return s if s else None
    if hasattr(value, "content"):
        s = str(getattr(value, "content")).strip()
        return s if s else None
    if hasattr(value, "value"):
        s = str(getattr(value, "value")).strip()
        return s if s else None
    s = str(value).strip()
    return s if s else None


def _extract_confidence(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if hasattr(value, "confidence"):
        try:
            return float(getattr(value, "confidence"))
        except (TypeError, ValueError):
            return None
    if isinstance(value, dict) and "confidence" in value:
        try:
            return float(value["confidence"])
        except (TypeError, ValueError):
            return None
    return None


def _get_field(fields: Any, *names: str) -> Any:
    if not fields:
        return None
    if isinstance(fields, dict):
        for name in names:
            if name in fields:
                return fields[name]
        lowered = {str(k).lower(): v for k, v in fields.items()}
        for name in names:
            v = lowered.get(name.lower())
            if v is not None:
                return v
        return None
    for name in names:
        try:
            v = fields.get(name)
            if v is not None:
                return v
        except Exception:
            pass
    return None


def _parse_items(raw_items: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    if not raw_items:
        return items
    for item in raw_items:
        if isinstance(item, dict):
            desc = _get_field(item, "Description", "description", "Item", "item")
            qty = _get_field(item, "Quantity", "quantity")
            unit_price = _get_field(item, "UnitPrice", "unitPrice", "unit_price")
            amount = _get_field(item, "Amount", "amount", "TotalPrice", "totalPrice")
            items.append(
                {
                    "description": _norm_text(getattr(desc, "content", desc)),
                    "quantity": _norm_text(getattr(qty, "content", qty)),
                    "unit_price": _norm_text(getattr(unit_price, "content", unit_price)),
                    "amount": _norm_text(getattr(amount, "content", amount)),
                }
            )
        else:
            fields = getattr(item, "fields", None)
            desc = _get_field(fields, "Description")
            qty = _get_field(fields, "Quantity")
            unit_price = _get_field(fields, "UnitPrice")
            amount = _get_field(fields, "Amount")
            items.append(
                {
                    "description": _norm_text(getattr(desc, "value", getattr(desc, "content", desc))),
                    "quantity": _norm_text(getattr(qty, "value", getattr(qty, "content", qty))),
                    "unit_price": _norm_text(getattr(unit_price, "value", getattr(unit_price, "content", unit_price))),
                    "amount": _norm_text(getattr(amount, "value", getattr(amount, "content", amount))),
                }
            )
    return items


def extract_and_validate_invoice(
    document_bytes: bytes,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    if required_fields is None:
        required_fields = [
            "VendorName",
            "InvoiceId",
            "InvoiceDate",
            "DueDate",
            "CustomerName",
            "CustomerAddress",
            "InvoiceTotal",
        ]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(model_id=model_id, body=document_bytes)
    result = poller.result()

    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = getattr(doc, "fields", None) if doc else None

    extracted: Dict[str, Any] = {}
    confidences: Dict[str, Optional[float]] = {}
    missing_fields: List[str] = []
    low_confidence_fields: List[str] = []

    for field_name in required_fields:
        raw = _get_field(fields, field_name)
        value = _norm_text(getattr(raw, "value", getattr(raw, "content", raw)))
        conf = _extract_confidence(raw)
        extracted[field_name] = value
        confidences[field_name] = conf
        if value is None:
            missing_fields.append(field_name)
        elif conf is None or conf < min_confidence:
            low_confidence_fields.append(field_name)

    line_items_raw = _get_field(fields, "Items", "LineItems", "lineItems")
    extracted_items = []
    items_confidence = _extract_confidence(line_items_raw)
    if line_items_raw is not None:
        value_obj = getattr(line_items_raw, "value", line_items_raw)
        if isinstance(value_obj, list):
            extracted_items = _parse_items(value_obj)
        else:
            extracted_items = _parse_items(value_obj if hasattr(value_obj, "__iter__") else [])
    extracted["Items"] = extracted_items
    confidences["Items"] = items_confidence
    if line_items_raw is not None and (items_confidence is None or items_confidence < min_confidence):
        low_confidence_fields.append("Items")

    is_valid = not missing_fields and not low_confidence_fields

    return {
        "valid": is_valid,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "confidence_threshold": min_confidence,
        "fields": extracted,
        "confidences": confidences,
        "raw_model_id": model_id,
    }
